.catalog-heading p{max-width:520px;color:var(--muted);font-size:12px;line-height:1.9}
.portfolio-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.portfolio-card{display:flex;min-height:280px;flex-direction:column;justify-content:space-between;gap:24px;padding:20px;border:1px solid var(--border);border-radius:18px;background:linear-gradient(145deg,rgba(255,255,255,.035),rgba(255,255,255,.012));transition:transform .25s ease,border-color .25s ease,background .25s ease}
.portfolio-card:hover{transform:translateY(-4px);border-color:rgba(151,174,255,.32);background:linear-gradient(145deg,rgba(125,153,230,.08),rgba(255,255,255,.014))}
.portfolio-card-top,.portfolio-card-bottom{display:flex;align-items:center;justify-content:space-between;gap:12px}
.portfolio-logo{display:grid;width:62px;height:62px;place-items:center;border:1px solid rgba(151,174,255,.2);border-radius:17px;background:linear-gradient(145deg,#1b2942,#241f3c);color:#b9cbff}
.portfolio-logo svg{width:38px;height:38px;fill:none;stroke:currentColor;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}
.portfolio-logo svg .solid{fill:currentColor;stroke:none}
.logo-help{color:#a8eee5;background:linear-gradient(145deg,#142f31,#1d2a43)}
.logo-cash{color:#ffd0a1;background:linear-gradient(145deg,#38251f,#322138)}
.logo-scan{color:#a8f0dd;background:linear-gradient(145deg,#14322c,#1d2e43)}
.logo-stock{color:#c7edaa;background:linear-gradient(145deg,#1c3325,#203c39)}
.logo-bot{color:#d0c3ff;background:linear-gradient(145deg,#252044,#202b48)}
.logo-privacy{color:#f0dcae;background:linear-gradient(145deg,#382f20,#292444)}
.portfolio-index,.portfolio-kind{color:#8f9bb2;font-size:9px;font-weight:700;letter-spacing:1px;text-transform:uppercase}
.portfolio-copy h3{margin:9px 0 8px;font-size:16px;letter-spacing:-.3px}
.portfolio-copy p{margin:0;color:var(--muted);font-size:11px;line-height:1.8}
.portfolio-status{color:#aeb9ce;font-size:9px;letter-spacing:.55px}
.portfolio-card-bottom a{color:#bac8fa;font-size:10px;font-weight:700;white-space:nowrap}
.portfolio-card-bottom a:hover{color:#fff}
.founder-link{margin:0 0 0 5px}
.ecosystem-card{transition:transform .25s ease,border-color .25s ease}
.ecosystem-card:hover{transform:translateY(-3px);border-color:rgba(151,174,255,.32)}
@media(max-width:850px){.portfolio-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.catalog-heading{grid-template-columns:1fr;gap:14px}}
@media(max-width:560px){.portfolio-grid{grid-template-columns:1fr}.portfolio-card{min-height:250px}.catalog-heading h2{font-size:36px}}
@media(prefers-reduced-motion:reduce){.hero-grid{animation:none!important}.portfolio-card,.ecosystem-card{transition:none!important}}

.ecosystem-domains{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:0 0 38px}
.ecosystem-domains article{min-width:0;padding:18px;border:1px solid var(--border);border-radius:15px;background:rgba(255,255,255,.018)}
.ecosystem-domains article>span{display:block;margin-bottom:24px;color:#9eafe0;font-size:9px;font-weight:750;letter-spacing:1.1px}
.ecosystem-domains h3{font-size:13px;line-height:1.45}
.ecosystem-domains p{margin:8px 0 0;color:var(--muted);font-size:10px;line-height:1.75}
.portfolio-kicker{margin:0 0 14px}
@media(max-width:850px){.ecosystem-domains{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:480px){.ecosystem-domains{grid-template-columns:1fr}.ecosystem-domains article{padding:16px}.ecosystem-domains article>span{margin-bottom:14px}}

.portfolio-logo-img{display:block;width:62px;height:62px;flex:0 0 62px;object-fit:contain;border:1px solid rgba(151,174,255,.2);border-radius:17px;background:#111827;padding:3px}
